Type-Safe Components Using Tokens

Now your components are type-constrained. This is where the magic happens:

// src/components/Button.tsx
import { SemanticColor, themes } from '../tokens/theme';
import { ReactNode } from 'react';
interface ButtonProps {
variant?: 'primary' | 'secondary' | 'ghost';
color?: SemanticColor;
size?: 'sm' | 'md' | 'lg';
children: ReactNode;
className?: string;
}
export const Button = ({
variant = 'primary',
color = 'primary',
size = 'md',
children,
className = '',
}: ButtonProps) => {
const sizeClasses = {
sm: 'px-2 py-1 text-sm',
md: 'px-4 py-2 text-base',
lg: 'px-6 py-3 text-lg',
};
// This TypeScript ensures `color` is always a valid semantic color
const baseStyle = `
bg-[var(--color-${color})]
hover:bg-[var(--color-${color}Hover)]
text-[var(--color-foreground)]
border border-[var(--color-border)]
rounded-md
transition-colors
${sizeClasses[size]}
${className}
`;
return (
<button
className={baseStyle}
data-variant={variant}
>
{children}
</button>
);
};

